     if (!['yes', 'no'].includes(values[name])) return { kind: 'error', message: `--${name} must be yes or no` };
     integrations[name] = values[name] === 'yes';
   }
+  let cfoaiReports: boolean | undefined;
+  if (values['cfoai-reports'] !== undefined) {
+    if (!['yes', 'no'].includes(values['cfoai-reports'])) return { kind: 'error', message: '--cfoai-reports must be yes or no' };
