   print(`  Model fallback     ${config.modelAccessFallbackTier ?? 'disabled'}`);
   print(`  Workers            ${config.runner === 'direct' ? 1 : config.parallelWorkers ?? 1} · ${config.runner ?? 'ao'}`);
 }

+const CFOAI_REPORTS_QUESTION = 'Share per-attempt cfo.ai reports with workspace members? Reports send the repository, run and task ids, task title and issue URL, size, model, tokens, cost, ceiling, outcome and decision text; they are visible to workspace members. y/N';
+
+async function chooseCfoaiReports(options: InitOptions, config: TallyConfig, readLine: PromptReader, existing: TallyConfig | null): Promise<void> {
+  if (!config.integrations.cfoai && config.budget.source !== 'cfoai') return;
+  const recorded = config.budget.cfoai && Object.hasOwn(config.budget.cfoai, 'publishRunContext');
+  const answer = options.cfoaiReports ?? (recorded ? config.budget.cfoai?.publishRunContext : undefined);
+  if (answer === undefined) {
+    // --yes is deliberately a default-no answer, never consent.
+    config.budget.cfoai = { ...(config.budget.cfoai ?? {}), publishRunContext: options.yes || options.dryRun ? false : parseYes(await readLine(CFOAI_REPORTS_QUESTION, 'N')) };
+  } else {
+    config.budget.cfoai = { ...(config.budget.cfoai ?? {}), publishRunContext: answer };
+  }
+  void existing;
+}
+
 function tiersFor(choice: 'codex' | 'claude-code' | 'mixed'): TallyConfig['tiers'] {
   // Mixed uses Codex for cheap work, then Sonnet and Opus for stronger attempts.
   return [0, 1, 2].map(index => {
@@ -385,6 +403,7 @@ async function reconfigureInit(options: InitOptions, configPath: string, print:
     // the proposed config so new integration settings (for example Entire's
     // automatic commit linking or cfo.ai Ari context) are persisted too.
     // Dry runs and --yes do not imply consent to external integration changes.
+    await chooseCfoaiReports(options, config, readLine, before);
     if (!options.dryRun && !options.yes) {
