type Obj = Record<string, any>;
const tools = ['list_orgs', 'inspect_scenarios', 'inspect_table_blocks', 'edit_table_blocks', 'inspect_pages', 'edit_pages', 'edit_memory'];
const budgetRows = ['Agent budget', 'Agent spend', 'Budget remaining'];
